/* drag-lint 1.55 XTABLE X3 fixture schema: IPCHART reaches MSCLIST by two paths (INSPRSLT, IINSP); TOOLGR is
   joined by a form on its key with no FK; NOKEY has no key; PAIRA / PAIRB are a 1:1 pair (each reaches the other). */
CREATE TABLE MSCLIST (MSCID INTEGER NOT NULL, NOTATION INTEGER, DECIMALS INTEGER,
  CONSTRAINT PK_MSC PRIMARY KEY (MSCID));
CREATE TABLE INSPRSLT (INSPID INTEGER NOT NULL, MSCID INTEGER,
  CONSTRAINT PK_INSP PRIMARY KEY (INSPID),
  CONSTRAINT FK_INSP_MSC FOREIGN KEY (MSCID) REFERENCES MSCLIST (MSCID));
CREATE TABLE IINSP (IID INTEGER NOT NULL, MSCID INTEGER,
  CONSTRAINT PK_IINSP PRIMARY KEY (IID),
  CONSTRAINT FK_IINSP_MSC FOREIGN KEY (MSCID) REFERENCES MSCLIST (MSCID));
CREATE TABLE TOOLGR (GRID INTEGER NOT NULL, GRNAME VARCHAR(20),
  CONSTRAINT PK_TOOLGR PRIMARY KEY (GRID));
CREATE TABLE NOKEY (NK INTEGER, NKNAME VARCHAR(20));
CREATE TABLE IPCHART (CHID INTEGER NOT NULL, INSPID INTEGER, IID INTEGER, GRID INTEGER, NK INTEGER,
  RVAL DOUBLE PRECISION,
  CONSTRAINT PK_IPCHART PRIMARY KEY (CHID),
  CONSTRAINT FK_IPCHART_INSP FOREIGN KEY (INSPID) REFERENCES INSPRSLT (INSPID),
  CONSTRAINT FK_IPCHART_IINSP FOREIGN KEY (IID) REFERENCES IINSP (IID));
CREATE TABLE PAIRA (PID INTEGER NOT NULL, ANAME VARCHAR(20),
  CONSTRAINT PK_PAIRA PRIMARY KEY (PID));
CREATE TABLE PAIRB (PID INTEGER NOT NULL, BNAME VARCHAR(20),
  CONSTRAINT PK_PAIRB PRIMARY KEY (PID),
  CONSTRAINT FK_B_A FOREIGN KEY (PID) REFERENCES PAIRA (PID));
ALTER TABLE PAIRA ADD CONSTRAINT FK_A_B FOREIGN KEY (PID) REFERENCES PAIRB (PID);
